// SECURE - Proper state transition validation
function updateStatus(uint256 id, Status newStatus) external onlyAuthorized {
    require(id < nextItemId, "Invalid item ID");

    Status currentStatus = items[id].status;
    require(_isValidTransition(currentStatus, newStatus), "Invalid state transition");
    require(newStatus != currentStatus, "Status unchanged");

    items[id].status = newStatus;
    items[id].lastUpdated = block.timestamp;

    emit StatusUpdated(id, currentStatus, newStatus);
}

function _isValidTransition(Status from, Status to) internal pure returns (bool) {
    // Define valid state transitions
    if (from == Status.Pending) return to == Status.Active || to == Status.Cancelled;
    if (from == Status.Active) return to == Status.Completed || to == Status.Cancelled;
    if (from == Status.Completed) return false; // Terminal state
    if (from == Status.Cancelled) return false; // Terminal state
    return false;
}
