    uint256 balanceBefore = IERC20(token).balanceOf(address(this));
    uint256 feeAmount = _calculateFees(token);
    uint256 balanceAfter = IERC20(token).balanceOf(address(this));

    uint256 actualCollected = balanceAfter - balanceBefore;
    require(actualCollected >= feeAmount, "Fee collection failed");

    accumulatedFees[token] += actualCollected;
}

function distributeFees(address token, uint256 amount) external {
    require(amount <= accumulatedFees[token], "Insufficient fees");
    accumulatedFees[token] -= amount;
    distributedFees[token] += amount;

    // Verify accounting consistency
    assert(distributedFees[token] <= accumulatedFees[token] + distributedFees[token]);
}
