// SECURE - Slippage-aware route optimization
struct RouteAnalysis {
    uint256 theoreticalOutput;
    uint256 expectedOutput; // After slippage
    uint256 slippageImpact;
    uint256 gasEstimate;
    uint256 netOutput; // After gas costs
}

function selectBestRoute(
    uint256 amountIn,
    Route[] memory routes,
    uint256 gasPrice
) external view returns (uint256 bestRouteIndex) {
    uint256 bestNetOutput = 0;

    for (uint256 i = 0; i < routes.length; i++) {
        RouteAnalysis memory analysis = _analyzeRoute(routes[i], amountIn, gasPrice);

        // Consider slippage impact and gas costs
        if (analysis.netOutput > bestNetOutput && 
            analysis.slippageImpact <= MAX_ACCEPTABLE_SLIPPAGE) {
            bestNetOutput = analysis.netOutput;
            bestRouteIndex = i;
        }
    }
}

function _analyzeRoute(
    Route memory route,
    uint256 amountIn,
    uint256 gasPrice
) internal view returns (RouteAnalysis memory) {
    uint256 theoreticalOutput = _getTheoreticalOutput(route, amountIn);
    uint256 slippageImpact = _calculateSlippageImpact(route, amountIn);
    uint256 expectedOutput = theoreticalOutput * (10000 - slippageImpact) / 10000;
    uint256 gasEstimate = _estimateGas(route);
    uint256 gasCost = gasEstimate * gasPrice;
    uint256 netOutput = expectedOutput > gasCost ? expectedOutput - gasCost : 0;

    return RouteAnalysis({
        theoreticalOutput: theoreticalOutput,
        expectedOutput: expectedOutput,
        slippageImpact: slippageImpact,
        gasEstimate: gasEstimate,
        netOutput: netOutput
    });
}
