function protectedSwap(
    uint256 amountIn,
    uint256 amountOutMin,
    uint256 maxGasPrice
) external {
    // Multi-vector MEV protection

    // 1. Prevent same-block arbitrage
    require(lastActionBlock[msg.sender] < block.number, "Same block action");

    // 2. Gas price manipulation protection
    require(tx.gasprice <= maxGasPrice, "Gas price too high");
    require(tx.gasprice <= block.basefee * 2, "Suspicious gas price");

    // 3. Oracle manipulation protection
    require(_validatePriceStability(), "Price instability detected");

    // 4. Time-based protection
    require(block.timestamp >= lastActionTime[msg.sender] + MIN_ACTION_INTERVAL, "Too frequent");

    lastActionBlock[msg.sender] = block.number;
    lastActionTime[msg.sender] = block.timestamp;

    _executeSwap(amountIn, amountOutMin);
}

function _validatePriceStability() internal view returns (bool) {
    uint256 currentPrice = getCurrentPrice();
    uint256 twapPrice = getTWAPPrice(STABILITY_PERIOD);

    uint256 deviation = currentPrice > twapPrice ?
        (currentPrice - twapPrice) * 10000 / twapPrice :
        (twapPrice - currentPrice) * 10000 / twapPrice;

    return deviation <= MAX_PRICE_DEVIATION;
}
