// VULNERABLE - Fixed decimal assumptions
function calculateMinOutput(
    uint256 amountIn,
    uint256 slippageBps
) external pure returns (uint256) {
    // Assumes all tokens have 18 decimals
    return amountIn * (10000 - slippageBps) / 10000;
}

// SECURE - Decimal-aware slippage calculations
function calculateMinOutput(
    uint256 amountIn,
    uint256 slippageBps,
    uint8 inputDecimals,
    uint8 outputDecimals,
    uint256 exchangeRate // In 18 decimal precision
) external pure returns (uint256) {
    require(slippageBps <= 10000, "Invalid slippage");
    require(inputDecimals <= 18 && outputDecimals <= 18, "Invalid decimals");

    // Normalize input to 18 decimals
    uint256 normalizedInput = inputDecimals < 18 ?
        amountIn * (10 ** (18 - inputDecimals)) :
        amountIn / (10 ** (inputDecimals - 18));

    // Calculate theoretical output in 18 decimals
    uint256 theoreticalOutput = normalizedInput * exchangeRate / 1e18;

    // Apply slippage
    uint256 minOutputNormalized = theoreticalOutput * (10000 - slippageBps) / 10000;

    // Convert back to output token decimals
    uint256 minOutput = outputDecimals < 18 ?
        minOutputNormalized / (10 ** (18 - outputDecimals)) :
        minOutputNormalized * (10 ** (outputDecimals - 18));

    return minOutput;
}

function swapWithDecimalAwareness(
    address tokenIn,
    address tokenOut,
    uint256 amountIn,
    uint256 slippageBps,
    uint256 deadline
) external {
    uint8 inputDecimals = IERC20Metadata(tokenIn).decimals();
    uint8 outputDecimals = IERC20Metadata(tokenOut).decimals();
    uint256 exchangeRate = _getExchangeRate(tokenIn, tokenOut);

    uint256 minOutput = calculateMinOutput(
        amountIn,
        slippageBps,
        inputDecimals,
        outputDecimals,
        exchangeRate
    );

    _executeSwap(tokenIn, tokenOut, amountIn, minOutput, deadline);
}
